// spec: specs/calculator.md (4.2–4.3) · кейсы: .qa/tests/calculator/CALC-COPY-01.md, CALC-COPY-02.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение. Буфер обмена — Chromium (desktop, Pixel 7).
import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, expectResult, copySummary, SET1, DEVICES } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

const TITLE = 'סיכום מחשבון כדאיות רכישת עסק – Biz4Sale';

test.describe('Калькулятор — чек-лист и копирование', () => {
  for (const tag of DEVICES) {
    test(`«העתקת סיכום»: заголовок, «נתונים:»/«תוצאות:», числа как на экране, дисклеймер в конце, тост #d4f37b ${tag} @prod-safe`, async ({ page, context, baseURL }) => {
      await context.grantPermissions(['clipboard-read', 'clipboard-write'], { origin: new URL(baseURL!).origin });
      await prepareReadOnly(context);
      await openCalculator(page);
      await fillInputs(page, SET1);
      await expectResult(page, 'תזרים חודשי משוער', '14,250 ₪');

      const text = await copySummary(page);
      expect(text.startsWith(TITLE), 'начинается с заголовка').toBe(true);
      for (const line of [
        'נתונים:',
        'מחיר רכישה: 500,000 ₪',
        'החזר הלוואה חודשי: 5,000 ₪',
        'שיעור מס: 23%',
        'תוצאות:',
        'סך השקעה ראשונית: 600,000 ₪',
        'הון עצמי נדרש: 400,000 ₪',
        'מס חודשי משוער: 5,750 ₪',
        'רווח חודשי לאחר מס: 19,250 ₪',
        'תזרים חודשי: 14,250 ₪',
        'תזרים שנתי: 171,000 ₪',
        'תשואה שנתית על ההון העצמי: 42.8%',
        'תשואה שנתית על ההשקעה הכוללת: 38.5%',
        'זמן החזר ההון העצמי: שנתיים ו־5 חודשים',
      ]) {
        expect(text, `строка «${line}»`).toContain(line);
      }
      expect(text, 'нет блока «שים לב:» при положительном תזרים').not.toContain('שים לב:');
      const lastLine = text.split('\n').filter(Boolean).pop()!;
      expect(lastLine, 'в конце дисклеймер').toContain('אינו ייעוץ פיננסי');
    });

    test(`«העתקת סיכום» при отрицательном תזרים — блок «שים לב:» с предупреждением #d4f37b #22ce3e ${tag} @prod-safe`, async ({ page, context, baseURL }) => {
      await context.grantPermissions(['clipboard-read', 'clipboard-write'], { origin: new URL(baseURL!).origin });
      await prepareReadOnly(context);
      await openCalculator(page);
      await fillInputs(page, { ...SET1, monthlyLoanPayment: '30000' });
      await expectResult(page, 'תזרים חודשי משוער', '-10,750 ₪');

      const text = await copySummary(page);
      expect(text).toContain('תזרים חודשי: -10,750 ₪');
      expect(text).toMatch(/שים לב:\n- התזרים החודשי שלילי:/);
      const lastLine = text.split('\n').filter(Boolean).pop()!;
      expect(lastLine, 'в конце дисклеймер').toContain('אינו ייעוץ פיננסי');
      expect(text.indexOf('שים לב:'), '«שים לב:» перед дисклеймером').toBeLessThan(text.lastIndexOf(lastLine));
    });
  }
});
